<?php
declare(strict_types=1);

function master_routes_v1(App $app,string $path):void
{
    $user=current_user();if(!$user)redirect(url('master-login'));if($user['role']!=='master'){http_response_code(403);simple_error('Acceso restringido','Este módulo requiere una sesión maestra.');return;}$section=explode('/',$path)[1]??'dashboard';
    if($section==='empresas')master_tenants_v131($app,$user);
    elseif($section==='planes')master_commercial_v2_no_demo($app,$user);
    elseif($section==='reportes')master_reports_v2_no_demo($app,$user);
    elseif($section==='blog')blog_admin_v1($app,$user,null);
    elseif($section==='auditoria')master_audit_v131($app,$user);
    elseif($section==='qa')master_qa_v103($app,$user);
    elseif($section==='cache')master_cache_v1($app,$user);
    elseif($section==='modules')master_modules_v12($app,$user);
    elseif(in_array($section,['configuracion','contenido'],true))master_settings_v1($app,$user,$section);
    else master_dashboard($app,$user);
}

function master_tenants_v131(App $app,array $user):void
{
    if(is_post()){
        verify_csrf();$action=(string)($_POST['action']??'save');
        try{
            if($action==='toggle'){$id=(int)$_POST['id'];$app->exec("UPDATE tenants SET is_active=1-is_active WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[$id]);audit($app,null,$user['id'],'toggle_tenant','tenant',$id);flash('success','Estado de la empresa actualizado.');}
            else{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=slugify((string)(($_POST['slug']??'')?:$name));if(!$name||!preg_match('/^[a-z0-9-]{2,100}$/',$slug)||is_demo_tenant_v12(['slug'=>$slug]))throw new RuntimeException('Nombre o enlace inválido.');$logo=upload_image('logo');$catalogLabel=($_POST['catalog_label']??'')==='Menú'?'Menú':'Catálogo';
                $physical=isset($_POST['physical_store_enabled'])?1:0;
                if($id){if(!$app->one("SELECT id FROM tenants WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[$id]))throw new RuntimeException('Empresa no disponible.');$sql='UPDATE tenants SET name=?,slug=?,email=?,phone=?,whatsapp=?,catalog_label=?,is_listed=?,physical_store_enabled=?'.($logo?',logo=?':'').' WHERE id=?';$values=[$name,$slug,trim((string)($_POST['email']??'')),trim((string)($_POST['phone']??'')),trim((string)($_POST['whatsapp']??'')),$catalogLabel,isset($_POST['is_listed'])?1:0,$physical];if($logo)$values[]=$logo;$values[]=$id;$app->exec($sql,$values);audit($app,null,$user['id'],'update_tenant','tenant',$id);}
                else{$email=strtolower(trim((string)($_POST['admin_email']??'')));$password=(string)($_POST['admin_password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)throw new RuntimeException('El administrador necesita correo válido y contraseña temporal de 12 caracteres.');$app->db->beginTransaction();$app->exec('INSERT INTO tenants(name,slug,email,phone,whatsapp,catalog_label,logo,is_listed,physical_store_enabled) VALUES(?,?,?,?,?,?,?,?,?)',[$name,$slug,trim((string)($_POST['email']??'')),trim((string)($_POST['phone']??'')),trim((string)($_POST['whatsapp']??'')),$catalogLabel,$logo,isset($_POST['is_listed'])?1:0,$physical]);$id=(int)$app->db->lastInsertId();$app->exec('INSERT INTO users(tenant_id,name,email,phone,password_hash,role,force_password_change) VALUES(?,?,?,?,?,"tenant_admin",1)',[$id,trim((string)($_POST['admin_name']??'Administrador')),$email,trim((string)($_POST['phone']??'')),password_hash($password,PASSWORD_DEFAULT)]);$app->exec('INSERT INTO branches(tenant_id,name,slug,whatsapp,phone,address,is_default,is_active) VALUES(?,"Sucursal principal","principal",?,?,"",1,1)',[$id,trim((string)($_POST['whatsapp']??'')),trim((string)($_POST['phone']??''))]);foreach([['San José centro',2500],['Alrededores',4000]] as $zone)$app->exec('INSERT INTO delivery_zones(tenant_id,name,price) VALUES(?,?,?)',[$id,$zone[0],$zone[1]]);$app->db->commit();audit($app,null,$user['id'],'create_tenant','tenant',$id);}
                flash('success','Empresa guardada correctamente.');
            }
        }catch(Throwable $exception){if($app->db->inTransaction())$app->db->rollBack();flash('error',$exception->getMessage());}redirect(url('master/empresas'));
    }
    $edit=!empty($_GET['edit'])?$app->one("SELECT * FROM tenants WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[(int)$_GET['edit']]):null;$rows=$app->all("SELECT t.*,(SELECT email FROM users WHERE tenant_id=t.id AND role='tenant_admin' ORDER BY id LIMIT 1) admin_email FROM tenants t WHERE t.slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY t.created_at DESC");
    admin_shell_start('Empresas',$user,null,'empresas');echo '<div class="split"><section class="card admin-card"><h2>'.($edit?'Editar empresa':'Nueva empresa').'</h2><form method="post" enctype="multipart/form-data">'.csrf_field().'<input type="hidden" name="id" value="'.(int)($edit['id']??0).'">'.field('Nombre comercial','name',$edit['name']??'',true).field('Enlace','slug',$edit['slug']??'').'<div class="split">'.field('WhatsApp de pedidos','whatsapp',$edit['whatsapp']??'',true).field('Teléfono','phone',$edit['phone']??'').'</div>'.field('Correo del negocio','email',$edit['email']??'',false,'email').'<div class="form-group"><label>Logo</label><input class="input" type="file" name="logo" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>Nombre del catálogo</label><select class="input" name="catalog_label"><option>Catálogo</option><option '.(($edit['catalog_label']??'')==='Menú'?'selected':'').'>Menú</option></select></div><label class="check-row"><input type="checkbox" name="physical_store_enabled" '.(($edit['physical_store_enabled']??0)?'checked':'').'> <span><strong>Activar modo tienda física</strong><small>Ventas, inventario, turnos, compras, CxC y CxP.</small></span></label><label><input type="checkbox" name="is_listed" '.(($edit['is_listed']??1)?'checked':'').'> Mostrar en directorio</label>';if(!$edit)echo '<hr><h3>Administrador principal</h3>'.field('Nombre','admin_name','',true).field('Correo de acceso','admin_email','',true,'email').field('Contraseña temporal','admin_password','',true,'password');echo '<button class="btn btn-block">Guardar empresa</button></form></section><section class="card admin-card"><h2>Empresas reales</h2><div class="table-wrap"><table class="table"><tr><th>Empresa</th><th>Modo</th><th>Enlace</th><th>Estado</th><th>Acción</th></tr>';foreach($rows as $row)echo '<tr><td><strong>'.e($row['name']).'</strong><br><small>'.e($row['admin_email']).'</small></td><td>'.($row['physical_store_enabled']?'Web + física':'Solo web').'</td><td><a target="_blank" href="'.url($row['slug']).'">/'.e($row['slug']).'</a></td><td><span class="status '.(!$row['is_active']?'status-off':'').'">'.($row['is_active']?'Activa':'Suspendida').'</span></td><td><a class="btn btn-light" href="?edit='.(int)$row['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$row['id'].'"><button class="btn '.($row['is_active']?'btn-danger':'btn-accent').'">'.($row['is_active']?'Suspender':'Activar').'</button></form></td></tr>';if(!$rows)echo '<tr><td colspan="5">Todavía no hay empresas reales registradas.</td></tr>';echo '</table></div></section></div>';admin_shell_end();
}

function master_audit_v131(App $app,array $user):void
{
    $rows=$app->all("SELECT a.*,u.name user_name,t.name tenant_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN tenants t ON t.id=a.tenant_id WHERE t.slug IS NULL OR t.slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY a.created_at DESC LIMIT 500");admin_shell_start('Auditoría',$user,null,'auditoria');echo '<section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Fecha</th><th>Empresa</th><th>Usuario</th><th>Acción</th><th>Entidad</th></tr>';foreach($rows as $row)echo '<tr><td>'.e(date('d/m/Y H:i',strtotime($row['created_at']))).'</td><td>'.e($row['tenant_name']??'Plataforma').'</td><td>'.e($row['user_name']??'Sistema').'</td><td>'.e($row['action']).'</td><td>'.e(($row['entity_type']??'').' #'.($row['entity_id']??'')).'</td></tr>';if(!$rows)echo '<tr><td colspan="5">No hay actividad registrada.</td></tr>';echo '</table></div></section>';admin_shell_end();
}

function master_qa_v103(App $app,array $user):void
{
    $checks=[];$add=function(string $area,string $name,bool $ok,string $detail='')use(&$checks):void{$checks[]=['area'=>$area,'name'=>$name,'ok'=>$ok,'detail'=>$detail];};
    foreach(['tenants','branches','branch_products','users','products','product_option_groups','product_options','orders','order_items','customer_addresses','search_logs','page_events','driver_profiles','driver_affiliations','driver_affiliation_branches','delivery_jobs','suppliers','product_inventory','inventory_movements','pos_shifts','sales','sale_items','purchases','accounts_receivable','accounts_payable','tenant_customers','customer_credit_profiles','restaurant_tables','pos_tickets','pos_ticket_items','pos_payments'] as $table){$exists=(bool)$app->one('SELECT 1 ok FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$table]);$add('Base de datos','Tabla '.$table,$exists,$exists?'Disponible':'No existe');}
    $demoLeak=(int)$app->one("SELECT COUNT(*) n FROM tenants WHERE slug IN ('tienda-demo','restaurante-demo') AND is_listed=1")['n'];$add('Aislamiento','Directorio sin datos demostrativos',$demoLeak===0,$demoLeak===0?'No se mezclan con negocios reales':'Se detectó contenido demostrativo listado');
    foreach(['index.php','app/core.php','app/v1.php','app/admin.php','app/admin_v1.php','assets/app.js','assets/app.bundle.css'] as $relative){$file=ROOT_PATH.'/'.$relative;$add('Aplicación',$relative,is_file($file)&&is_readable($file),is_file($file)?filesize($file).' bytes':'No encontrado');}
    $uploads=ROOT_PATH.'/uploads';$add('Contenido existente','Carpeta uploads',is_dir($uploads)&&is_readable($uploads),is_dir($uploads)?'Disponible':'No existe; restaura las imágenes cargadas por usuarios');
    $blankSettings=$app->all('SELECT `key` FROM settings WHERE value=?',['']);$blankValuesRespected=true;foreach($blankSettings as $blankSetting){if($app->setting((string)$blankSetting['key'],'__FISITAPP_FALLBACK__')!==''){$blankValuesRespected=false;break;}}$add('Personalización','Campos guardados vacíos',$blankValuesRespected,$blankSettings?count($blankSettings).' campo(s) permanecen vacíos':'No hay campos vacíos guardados; la regla está activa');
    $media=[];foreach($app->all("SELECT `value` media FROM settings WHERE `key` LIKE '%image%' OR `key`='platform_logo'") as $row)$media[]=$row['media'];foreach($app->all('SELECT logo media FROM tenants WHERE logo IS NOT NULL AND logo!=""') as $row)$media[]=$row['media'];foreach($app->all('SELECT image media FROM tenant_content WHERE image IS NOT NULL AND image!=""') as $row)$media[]=$row['media'];foreach($app->all('SELECT image media,gallery FROM products WHERE (image IS NOT NULL AND image!="") OR gallery IS NOT NULL') as $row){$media[]=$row['media'];foreach(json_decode((string)($row['gallery']??''),true)?:[] as $galleryImage)$media[]=$galleryImage;}foreach($app->all('SELECT media_url media FROM posts WHERE media_type="image" AND media_url IS NOT NULL AND media_url!=""') as $row)$media[]=$row['media'];$missingMedia=[];$base=rtrim(url(),'/').'/';foreach(array_unique(array_filter(array_map('strval',$media))) as $mediaUrl){if(!str_starts_with($mediaUrl,$base))continue;$relative=ltrim(substr($mediaUrl,strlen($base)),'/');if($relative===''||str_contains($relative,'..'))continue;if(!is_file(ROOT_PATH.'/'.$relative))$missingMedia[]=$relative;}$add('Contenido existente','Archivos usados por páginas',!$missingMedia,$missingMedia?'Faltan '.count($missingMedia).': '.implode(', ',array_slice($missingMedia,0,5)).(count($missingMedia)>5?'…':''):'Todas las referencias locales existen');
    $failed=count(array_filter($checks,fn($check)=>!$check['ok']));admin_shell_start('QA integral del sitio',$user,null,'qa');echo '<section class="card admin-card"><span class="tag">DIAGNÓSTICO</span><h2>'.($failed?'Se encontraron '.$failed.' fallos':'Todas las verificaciones pasaron').'</h2><p class="muted">Comprueba estructura, módulos, aislamiento y lectura pública de archivos sin incorporar datos demostrativos al panel maestro.</p><p><a class="btn btn-light" href="'.url('master/qa').'">Repetir QA</a></p></section><section class="card admin-card" style="margin-top:20px"><div class="table-wrap"><table class="table"><tr><th>Área</th><th>Prueba</th><th>Resultado</th><th>Detalle</th></tr>';foreach($checks as $check)echo '<tr><td>'.e($check['area']).'</td><td>'.e($check['name']).'</td><td><span class="status '.($check['ok']?'':'status-off').'">'.($check['ok']?'✓ Correcto':'✕ Falló').'</span></td><td>'.e($check['detail']).'</td></tr>';echo '</table></div></section>';admin_shell_end();
}

function master_cache_v1(App $app,array $user):void
{
    if(!is_post()){
        admin_shell_start('Caché del sitio',$user,null,'cache');
        echo '<section class="card admin-card cache-panel"><span class="tag">RENDIMIENTO</span><h2>Renovar caché de FISITAAP</h2><p class="muted">Utiliza esta herramienta cuando acabas de actualizar o si notas estilos antiguos, carga incompleta o secciones que no aparecen.</p><form method="post" action="'.url('master/cache').'" onsubmit="return confirm(\'¿Vaciar la caché del sitio y renovar los archivos visibles?\')">'.csrf_field().'<button class="btn">↻ Vaciar caché ahora</button></form><p class="muted cache-note">No elimina usuarios, configuraciones, productos, pedidos, sesiones ni carritos.</p></section>';
        admin_shell_end();return;
    }
    verify_csrf();
    $version=(string)round(microtime(true)*1000);
    $app->exec('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',['cache_version',$version]);
    if(function_exists('opcache_reset'))@opcache_reset();
    audit($app,null,(int)$user['id'],'purge_site_cache','settings');
    header('Clear-Site-Data: "cache"');
    header('Cache-Control: no-store, max-age=0');
    layout_start('Caché eliminada',null,true);
    echo '<main class="auth-page"><section class="card auth-card"><span class="tag">MANTENIMIENTO</span><h1>Caché eliminada</h1><p class="muted">Se renovaron los recursos del sitio, la caché PWA y OPcache cuando está disponible. No se borraron sesiones, carritos ni información de usuarios.</p><p id="cachePurgeStatus">Finalizando limpieza en este navegador…</p></section></main><script>window.FISITAPP_CACHE_PURGE=true;Promise.all([(window.caches?caches.keys().then(keys=>Promise.all(keys.map(key=>caches.delete(key)))):Promise.resolve()),(navigator.serviceWorker?navigator.serviceWorker.getRegistrations().then(items=>Promise.all(items.map(item=>item.unregister()))):Promise.resolve())]).finally(()=>{document.getElementById("cachePurgeStatus").textContent="Listo. Recargando el panel con archivos nuevos…";setTimeout(()=>location.replace("'.url('master?cache_cleared=1').'"),700)});</script>';
    layout_end();
}

function tenant_admin_routes_v1(App $app,string $path):void
{
    $user=current_user();if(!$user)redirect(url('owner-login'));if($user['role']==='driver')redirect(url('driver'));if(!in_array($user['role'],['tenant_admin','manager','editor','kitchen','cashier'],true)){http_response_code(403);simple_error('Acceso restringido','Este módulo requiere una sesión de negocio.');return;}$tenant=$app->one('SELECT * FROM tenants WHERE id=?',[$user['tenant_id']]);if(!$tenant)exit('Empresa no disponible');$section=explode('/',$path)[1]??'dashboard';$physicalSections=['ventas','cobro','express-pendientes','turnos','compras','cxc','cxp'];$allowed=['dashboard','sucursales','pedidos','cocina','ventas','cobro','express-pendientes','turnos','inventario','compras','cxc','cxp','repartidor','express','productos','opciones','categorias','delivery','cupones','clientes','fidelizacion','contenido','blog','contactos','reportes','usuarios','auditoria','configuracion','impresion','recibo'];if(!in_array($section,$allowed,true))$section='dashboard';if(in_array($section,$physicalSections,true)&&!physical_store_v14($tenant)){http_response_code(403);simple_error('Modo tienda física inactivo','Activa este modo desde la empresa para usar el módulo.');return;}require_section_permission($user,$section);require_module_v12($app,$tenant,section_module_v12($section));
    if($section==='dashboard')tenant_dashboard($app,$user,$tenant);
    elseif($section==='sucursales')tenant_branches_admin_v1($app,$user,$tenant);
    elseif($section==='pedidos')tenant_orders_v6($app,$user,$tenant);
    elseif($section==='cocina')tenant_kitchen_v142($app,$user,$tenant);
    elseif($section==='repartidor')tenant_delivery_board_v4($app,$user,$tenant);
    elseif($section==='express')tenant_express_v12($app,$user,$tenant);
    elseif($section==='productos')tenant_products_v14($app,$user,$tenant);
    elseif($section==='cobro'||$section==='express-pendientes'){if(($tenant['catalog_label']??'')!=='Menú'){http_response_code(403);simple_error('Modo Menú requerido','Usa la ventana de ventas del catálogo.');return;}if($section==='cobro')pos_collect_148($app,$user,$tenant);else pos_express_pending_148($app,$user,$tenant);}
    elseif($section==='ventas')tenant_sales_v141($app,$user,$tenant);
    elseif($section==='turnos')tenant_shifts_v142($app,$user,$tenant);
    elseif($section==='inventario')tenant_inventory_v14($app,$user,$tenant);
    elseif($section==='compras')tenant_purchases_v14($app,$user,$tenant);
    elseif($section==='cxc')tenant_accounts_v14($app,$user,$tenant,'cxc');
    elseif($section==='cxp')tenant_accounts_v14($app,$user,$tenant,'cxp');
    elseif($section==='opciones')tenant_product_options_v5($app,$user,$tenant);
    elseif($section==='categorias')tenant_categories_v6($app,$user,$tenant);
    elseif(in_array($section,['delivery','cupones'],true))tenant_simple_module_v3($app,$user,$tenant,$section);
    elseif($section==='reportes')tenant_reports_v14($app,$user,$tenant);
    elseif($section==='contenido')tenant_content_admin_v6($app,$user,$tenant);
    elseif($section==='blog')blog_admin_v1($app,$user,(int)$tenant['id']);
    elseif($section==='contactos')contacts_admin_v1($app,$user,$tenant);
    elseif($section==='configuracion')tenant_settings_v1($app,$user,$tenant);
    elseif($section==='impresion')tenant_printer_v142($app,$user,$tenant);
    elseif($section==='recibo')tenant_receipt_v142($app,$user,$tenant);
    elseif($section==='clientes')tenant_customers_v141($app,$user,$tenant);
    elseif($section==='fidelizacion')tenant_loyalty_v12($app,$user,$tenant);
    elseif($section==='auditoria')audit_view_v1($app,$user,(int)$tenant['id']);
    else tenant_team_v1($app,$user,$tenant);
}

function valid_report_dates_v1():array
{
    $from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if($from>$to)[$from,$to]=[$to,$from];return[$from,$to];
}

function csv_download_v1(string $filename,array $headers,array $rows):never
{
    $safe=static function($value){if(!is_string($value))return $value;$trimmed=ltrim($value);return $trimmed!==''&&in_array($trimmed[0],['=','+','-','@'],true)?"'".$value:$value;};header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,array_map($safe,$headers));foreach($rows as $row)fputcsv($out,array_map($safe,array_values($row)));fclose($out);exit;
}

function tenant_reports_v1(App $app,array $user,array $tenant):void
{
    [$from,$to]=valid_report_dates_v1();$params=[$tenant['id'],$from,$to];$summary=$app->one("SELECT COUNT(*) orders_count,COALESCE(SUM(total),0) sales,COALESCE(AVG(total),0) avg_ticket,COUNT(DISTINCT user_id) customers,COALESCE(SUM(discount_total),0) discounts FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!='cancelled'",$params);$events=$app->all("SELECT event_type,COUNT(*) total FROM page_events WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? GROUP BY event_type",$params);$eventMap=array_column($events,'total','event_type');$conversion=!empty($eventMap['catalog_view'])?round(((int)($eventMap['checkout_completed']??0)/(int)$eventMap['catalog_view'])*100,1):0;
    $products=$app->all("SELECT oi.product_name,SUM(oi.quantity) qty,SUM(oi.line_subtotal+oi.line_tax) total FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.tenant_id=? AND DATE(o.created_at) BETWEEN ? AND ? AND o.status!='cancelled' GROUP BY oi.product_name ORDER BY total DESC LIMIT 30",$params);
    $categories=$app->all("SELECT COALESCE(c.name,'Sin categoría') label,COUNT(DISTINCT o.id) orders_count,COALESCE(SUM(oi.line_subtotal+oi.line_tax),0) total FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN products p ON p.id=oi.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE o.tenant_id=? AND DATE(o.created_at) BETWEEN ? AND ? AND o.status!='cancelled' GROUP BY c.id,c.name ORDER BY total DESC",$params);
    $payments=$app->all("SELECT payment_method label,COUNT(*) orders_count,SUM(total) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!='cancelled' GROUP BY payment_method ORDER BY total DESC",$params);$delivery=$app->all("SELECT delivery_type label,COUNT(*) orders_count,SUM(total) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!='cancelled' GROUP BY delivery_type ORDER BY total DESC",$params);$statuses=$app->all("SELECT status label,COUNT(*) orders_count,SUM(total) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? GROUP BY status ORDER BY orders_count DESC",$params);$hours=$app->all("SELECT HOUR(created_at) label,COUNT(*) orders_count,SUM(total) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!='cancelled' GROUP BY HOUR(created_at) ORDER BY label",$params);$coupons=$app->all("SELECT COALESCE(coupon_code,'Sin cupón') label,COUNT(*) orders_count,SUM(discount_total) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? GROUP BY coupon_code ORDER BY total DESC",$params);$searches=$app->all("SELECT query label,COUNT(*) searches,SUM(result_count=0) no_results FROM search_logs WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? GROUP BY query ORDER BY searches DESC LIMIT 30",$params);
    if(($_GET['export']??'')==='csv'){csv_download_v1('reporte-fisitapp-'.$from.'-'.$to.'.csv',['Producto','Cantidad','Total'],array_map(fn($r)=>[$r['product_name'],$r['qty'],$r['total']],$products));}
