icación?\')">'.csrf_field().'<input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$post['id'].'"><button class="btn btn-danger">Eliminar</button></form></div></article>';echo '</section></div>';admin_shell_end();
