function master_commercial_v1(App $app,array $user):void
{
    if(is_post()){verify_csrf();$plan=trim((string)$_POST['plan']);$expires=trim((string)($_POST['expires_at']??''));$app->exec("UPDATE tenants SET plan=?,expires_at=?,is_active=? WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[$plan?:'Profesional',$expires?:null,isset($_POST['is_active'])?1:0,(int)$_POST['id']]);flash('success','Plan actualizado.');redirect(url('master/planes'));}$rows=$app->all("SELECT t.*,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id) users_count,(SELECT COUNT(*) FROM products p WHERE p.tenant_id=t.id) products_count,(SELECT COUNT(*) FROM orders o WHERE o.tenant_id=t.id) orders_count FROM tenants t WHERE t.slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY t.name");admin_shell_start('Planes y vencimientos',$user,null,'planes');echo '<section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Empresa</th><th>Uso</th><th>Plan y vencimiento</th><th>Estado</th></tr>';foreach($rows as $row)echo '<tr><td><strong>'.e($row['name']).'</strong><br>/'.e($row['slug']).'</td><td>'.e($row['users_count']).' usuarios<br>'.e($row['products_count']).' productos<br>'.e($row['orders_count']).' pedidos</td><td><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><input class="input compact" name="plan" value="'.e($row['plan']).'" required><input class="input compact" type="date" name="expires_at" value="'.e($row['expires_at']).'"><label><input type="checkbox" name="is_active" '.($row['is_active']?'checked':'').'> Activa</label><button class="btn btn-light">Guardar</button></form></td><td><span class="status '.(!$row['is_active']?'status-off':'').'">'.($row['is_active']?'Activa':'Suspendida').'</span></td></tr>';echo '</table></div></section>';admin_shell_end();
}

function master_settings_v1(App $app,array $user,string $section):void
{
    $contentKeys=['site_name','master_whatsapp','platform_primary_color','platform_accent_color','hero_tag','hero_button','hero_whatsapp_message','home_slide_1_title','home_slide_1_text','home_slide_2_title','home_slide_2_text','home_slide_3_title','home_slide_3_text','features_tag','features_title','feature_1_title','feature_1_text','feature_2_title','feature_2_text','feature_3_title','feature_3_text','directory_tag','directory_title','directory_empty','contact_tag','contact_title','contact_text','contact_button','footer_text','footer_links_title','footer_contact_title','footer_credit','facebook_url','instagram_url','tiktok_url'];
    $keys=$section==='contenido'?$contentKeys:['site_name','master_whatsapp','smtp_host','smtp_port','smtp_user','smtp_pass','smtp_encryption','smtp_from_email','smtp_from_name'];
    if(is_post()){
        verify_csrf();
        foreach($keys as $key){
            $value=trim((string)($_POST[$key]??''));
            if($key==='smtp_pass'&&$value==='')continue;
            if($key==='smtp_pass')$value=secret_encrypt_v1($app,$value);
            if(str_ends_with($key,'_color')&&!preg_match('/^#[0-9a-fA-F]{6}$/',$value))continue;
            $app->exec('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$key,$value]);
        }
        if($section==='contenido')foreach(['platform_logo','home_slide_1_image','home_slide_2_image','home_slide_3_image','feature_1_image','feature_2_image','feature_3_image'] as $imageKey)if($image=upload_image($imageKey))$app->exec('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$imageKey,$image]);
        flash('success','Configuración guardada.');redirect(url('master/'.$section));
    }
    $labels=['site_name'=>'Nombre de plataforma','master_whatsapp'=>'WhatsApp comercial','platform_primary_color'=>'Color principal','platform_accent_color'=>'Color marfil/acento','hero_tag'=>'Etiqueta del slider','hero_button'=>'Texto del botón principal','hero_whatsapp_message'=>'Mensaje inicial de WhatsApp','home_slide_1_title'=>'Slider 1 · título','home_slide_1_text'=>'Slider 1 · texto','home_slide_2_title'=>'Slider 2 · título','home_slide_2_text'=>'Slider 2 · texto','home_slide_3_title'=>'Slider 3 · título','home_slide_3_text'=>'Slider 3 · texto','features_tag'=>'Etiqueta de beneficios','features_title'=>'Título de beneficios','feature_1_title'=>'Beneficio 1 · título','feature_1_text'=>'Beneficio 1 · texto','feature_2_title'=>'Beneficio 2 · título','feature_2_text'=>'Beneficio 2 · texto','feature_3_title'=>'Beneficio 3 · título','feature_3_text'=>'Beneficio 3 · texto','directory_tag'=>'Etiqueta del directorio','directory_title'=>'Título del directorio','directory_empty'=>'Texto sin negocios','contact_tag'=>'Etiqueta de contacto','contact_title'=>'Título de contacto','contact_text'=>'Texto de contacto','contact_button'=>'Texto del botón WhatsApp','footer_text'=>'Descripción del pie de página','footer_links_title'=>'Título de enlaces del pie','footer_contact_title'=>'Título de contacto del pie','footer_credit'=>'Crédito del pie de página','facebook_url'=>'Facebook','instagram_url'=>'Instagram','tiktok_url'=>'TikTok','smtp_host'=>'Servidor SMTP','smtp_port'=>'Puerto SMTP','smtp_user'=>'Usuario SMTP','smtp_pass'=>'Contraseña SMTP','smtp_encryption'=>'Seguridad: tls o ssl','smtp_from_email'=>'Correo remitente','smtp_from_name'=>'Nombre remitente'];
    admin_shell_start($section==='contenido'?'Diseño y contenido oficial':'Configuración y correo',$user,null,$section);
    echo '<section class="card admin-card settings-panel"><form method="post" enctype="multipart/form-data">'.csrf_field();
    if($section==='contenido')echo '<div class="form-group"><label>Logo oficial</label><input class="input" type="file" name="platform_logo" accept="image/jpeg,image/png,image/webp"></div>';
    foreach($keys as $key)echo field($labels[$key],$key,$key==='smtp_pass'?'':$app->setting($key,$key==='platform_primary_color'?'#1f7a45':($key==='platform_accent_color'?'#dfe9c8':'')),false,$key==='smtp_pass'?'password':($key==='smtp_port'?'number':(str_ends_with($key,'_color')?'color':'text')));
    if($section==='contenido'){
        for($i=1;$i<=3;$i++)echo '<div class="form-group"><label>Slider '.$i.' · imagen</label><input class="input" type="file" name="home_slide_'.$i.'_image" accept="image/jpeg,image/png,image/webp"></div>';
        for($i=1;$i<=3;$i++)echo '<div class="form-group"><label>Beneficio '.$i.' · imagen</label><input class="input" type="file" name="feature_'.$i.'_image" accept="image/jpeg,image/png,image/webp"></div>';
    }
    echo '<button class="btn">Guardar cambios</button></form></section>';admin_shell_end();
}
